	-- CooldownText
	["Cooldown Timers"] = "Temporizadores de recarga", -- draft
	["Large countdown numbers on action bar cooldowns and nameplate auras, coloured by time left."] = "Números grandes de contagem regressiva nas recargas das barras de ação e nas auras das placas de identificação, coloridos pelo tempo restante.", -- draft
	["Countdowns on every cooldown, coloured by how long you still have to wait."] = "Contagens regressivas em cada recarga, coloridas pelo quanto você ainda tem que esperar.", -- draft
	["Countdown numbers on action bar cooldowns and nameplate auras, coloured by the time left."] = "Números de contagem regressiva nas recargas das barras de ação e nas auras das placas de identificação, coloridos pelo tempo restante.", -- draft
	["Show On"] = "Mostrar em", -- draft
	["Action, pet, stance and flyout buttons."] = "Botões de ação, ajudante, postura e menus suspensos.", -- draft
	["Nameplate Auras"] = "Auras das placas de identificação", -- draft
	["Buff, debuff and crowd control icons on nameplates. While Buffs & Debuffs puts your debuffs on enemy nameplates, those icons are MelloUI's own and show their own time: this switch does not reach them."] = "Ícones de bônus, penalidades e controle de grupo nas placas de identificação. Enquanto Bônus e penalidades põe suas penalidades nas placas dos inimigos, esses ícones são do MelloUI e mostram o próprio tempo: este interruptor não os alcança.", -- draft
	["Timer"] = "Temporizador", -- draft
	["Minimum Duration"] = "Duração mínima", -- draft
	["Cooldowns shorter than this show no text (2 s skips the global cooldown)."] = "Recargas mais curtas que isso não mostram texto (2 s ignora a recarga global).", -- draft
	["Text Size"] = "Tamanho do texto", -- draft
	["Text height relative to the icon size."] = "Altura do texto em relação ao tamanho do ícone.", -- draft
	["Show Tenths Below 5s"] = "Décimos abaixo de 5 s", -- draft
	["Show 4.3 instead of 5 when the cooldown is about to finish."] = "Mostra 4.3 em vez de 5 quando a recarga está quase no fim.", -- draft
	["Colour And Size By Time Left"] = "Cor e tamanho pelo tempo restante", -- draft
	["Red and larger under 5 s (1.3 times the Text Size), yellow under a minute, dim white and smaller for minutes (0.8 times), grey and smaller still for hours (0.75 times). Off: every timer is white at the Text Size."] = "Vermelho e maior abaixo de 5 s (1,3 vez o Tamanho do texto), amarelo abaixo de um minuto, branco apagado e menor para minutos (0,8 vez), cinza e menor ainda para horas (0,75 vez). Desligado: todo temporizador é branco no Tamanho do texto.", -- draft
	-- Tweaks
	["Tweaks"] = "Ajustes", -- draft
	["Hide the micro menu and bag bar, and scale the floating combat text."] = "Esconde o micromenu e a barra de bolsas, e redimensiona o texto de combate flutuante.", -- draft
	["Small knobs with a big effect. Hide what you never click, scale what you never see."] = "Botõezinhos com grande efeito. Esconda o que você nunca clica, aumente o que você nunca vê.", -- draft
	["Hide Frames"] = "Esconder quadros", -- draft
	["Hide Micro Menu"] = "Esconder micromenu", -- draft
	["Hide the row of menu buttons (character, spellbook, talents, ...). Still shown while Edit Mode is open."] = "Esconde a fileira de botões de menu (personagem, grimório, talentos, ...). Continua visível com o Modo de edição aberto.", -- draft
	["Hide Bag Bar"] = "Esconder barra de bolsas", -- draft
	["Hide the backpack and bag slot buttons. Still shown while Edit Mode is open. Bags can still be opened with their keybinds."] = "Esconde os botões da mochila e dos compartimentos de bolsa. Continua visível com o Modo de edição aberto. As bolsas ainda abrem pelas teclas de atalho.", -- draft
	["Hide Minimap Coordinates"] = "Esconder coordenadas do minimapa", -- draft
	["Hide the player coordinates the client writes under the minimap."] = "Esconde as coordenadas do jogador que o cliente escreve sob o minimapa.", -- draft
	["Bag Slots On Bag Window"] = "Compartimentos de bolsa na janela de bolsas", -- draft
	["While the bag bar is hidden, show the bag slots under the open bag window so bags can still be equipped and removed. Works with and without the Combine Bags option."] = "Enquanto a barra de bolsas está escondida, mostra os compartimentos de bolsa sob a janela de bolsa aberta, para que ainda dê para equipar e tirar bolsas. Funciona com e sem a opção Combinar bolsas.", -- draft
	["Collapse Arrow"] = "Seta de recolher", -- draft
	["An arrow beside the backpack folds the bag slots away so only the backpack shows; click it again to bring them back. While you hold an item they come out by themselves, so a new bag can be dropped into a slot. The game remembers which way you left it."] = "Uma seta ao lado da mochila recolhe os compartimentos de bolsa para que só a mochila apareça; clique de novo para trazê-los de volta. Enquanto você segura um item, eles saem sozinhos, para que uma bolsa nova possa ser solta num compartimento. O jogo lembra como você deixou.", -- draft
	["Chat"] = "Bate-papo", -- draft
	["Chat Notices"] = "Avisos no bate-papo", -- draft
	["Lines MelloUI writes to chat on its own: a learned dungeon entrance, settings restored from the backup, hints. Replies to slash commands, and the notices you send to the chat (Send To Chat Instead), always show."] = "Linhas que o MelloUI escreve no bate-papo por conta própria: uma entrada de masmorra aprendida, configurações restauradas do backup, dicas. Respostas a comandos de barra e os avisos que você manda para o bate-papo (Enviar ao bate-papo) sempre aparecem.", -- draft
	["Notices"] = "Avisos", -- draft
	["On-screen Notices"] = "Avisos na tela", -- draft
	["One short line in the upper third of the screen when MelloUI has news for you: a route set or finished, a service remembered, a dungeon's quests listed. It fades after a few seconds. Move it in Edit Layout."] = "Uma linha curta no terço superior da tela quando o MelloUI tem novidades para você: uma rota definida ou concluída, um serviço lembrado, as missões de uma masmorra listadas. Ela some após alguns segundos. Mova-a em Editar layout.", -- draft
	["Send To Chat Instead"] = "Enviar ao bate-papo", -- draft
	["Write these lines in the chat instead of showing them on the screen. They show there even while Chat Notices is off."] = "Escreve estas linhas no bate-papo em vez de mostrá-las na tela. Elas aparecem lá mesmo com Avisos no bate-papo desligado.", -- draft
	["Notice Sounds"] = "Sons dos avisos", -- draft
	["A short chime with each notice: the map's tracking sound for a new destination (left out while the World Marker's own sound plays for it), a softer one when you arrive."] = "Um toque curto a cada aviso: o som de rastreamento do mapa para um novo destino (omitido quando o próprio som do Marcador do mundo toca), um mais suave quando você chega.", -- draft
	["Text Shade"] = "Sombra do texto", -- draft
	["A soft dark shade behind the text MelloUI shows on the world, so it reads on bright ground: the zone name when you enter a new area (with its subzone and PvP lines), the game's messages in the middle of the screen (red errors, yellow quest progress, raid warnings and boss emotes), the Route's World Marker, the names on the unit frames (yours, your pet's, your targets' targets' and the party's) and on the nameplates, and the channel tags and links on the chat's parchment. No outline on the zone name and the messages (Outlined Text adds it back); the game's colours stay. Off: the game's own look, and no shade behind any of them."] = "Uma sombra escura e suave atrás do texto que o MelloUI mostra sobre o mundo, para que seja lido em fundos claros: o nome da zona ao entrar numa área nova (com as linhas de subzona e JxJ), as mensagens do jogo no meio da tela (erros vermelhos, progresso de missão amarelo, avisos de raide e expressões de chefes), o Marcador do mundo da Rota, os nomes nos quadros de unidade (o seu, do seu ajudante, dos alvos dos seus alvos e do grupo) e nas placas de identificação, e as etiquetas de canal e links no pergaminho do bate-papo. Sem contorno no nome da zona e nas mensagens (Texto contornado o devolve); as cores do jogo ficam. Desligado: o visual do jogo, e nenhuma sombra atrás deles.", -- draft
	["Outlined Text"] = "Texto contornado", -- draft
	["Draw the text MelloUI shows on the world with an outline: the on-screen notice's lines, Combat Text's lines and the Gains lines, and, while Text Shade is on, the zone text and the game's messages in the middle of the screen. Off: soft text on a dark shade."] = "Desenha com contorno o texto que o MelloUI mostra sobre o mundo: as linhas do aviso na tela, as do Texto de combate e as linhas de ganhos e, enquanto Sombra do texto está ligada, o texto da zona e as mensagens do jogo no meio da tela. Desligado: texto suave sobre uma sombra escura.", -- draft
	["Combat Text"] = "Texto de combate", -- draft
	["Numbers Over Enemies"] = "Números sobre os inimigos", -- draft
	["The size of the numbers over the enemies and the ones you heal: the game's own, and Your Damage's when MelloUI draws them (one or the other shows). 1.0 is the game's size."] = "O tamanho dos números sobre os inimigos e sobre quem você cura: os do jogo, e os de Seu dano quando o MelloUI os desenha (um ou outro aparece). 1.0 é o tamanho do jogo.", -- draft
	["Bar Layout"] = "Layout das barras", -- draft
	["Which Bar"] = "Qual barra", -- draft
	["The bar the rows below set: its rows, icons, icon size and padding, saved into your active Edit Mode layout as Edit Mode saves them, once you let a slider go (out of combat). The game shows them after a reload: type /reload (MelloUI says so once). One of the game's preset layouts is copied first: you are asked once."] = "A barra que as linhas abaixo ajustam: fileiras, ícones, tamanho do ícone e espaçamento, salvos no seu layout ativo do Modo de edição como o Modo de edição os salva, assim que você solta um controle deslizante (fora de combate). O jogo os mostra após recarregar: digite /reload (o MelloUI avisa uma vez). Um dos layouts predefinidos do jogo é copiado primeiro: você é perguntado uma vez.", -- draft
	["Action Bar 1"] = "Barra de ação 1", -- draft
	["Action Bar 2"] = "Barra de ação 2", -- draft
	["Action Bar 3"] = "Barra de ação 3", -- draft
	["Action Bar 4"] = "Barra de ação 4", -- draft
	["Action Bar 5"] = "Barra de ação 5", -- draft
	["Action Bar 6"] = "Barra de ação 6", -- draft
	["Action Bar 7"] = "Barra de ação 7", -- draft
	["Action Bar 8"] = "Barra de ação 8", -- draft
	["Stance Bar"] = "Barra de Postura", -- draft
	["Pet Bar"] = "Barra do ajudante", -- draft
	["Rows"] = "Fileiras", -- draft
	["How many rows the bar's buttons stand in (columns, on a bar stood upright in Edit Mode)."] = "Em quantas fileiras ficam os botões da barra (colunas, numa barra posta na vertical no Modo de edição).", -- draft
	["Icons"] = "Ícones", -- draft
	["How many of the bar's buttons show."] = "Quantos botões da barra aparecem.", -- draft
	["Icon Size"] = "Tamanho do ícone", -- draft
	["The size of the bar's buttons. 100% is the game's own size."] = "O tamanho dos botões da barra. 100% é o tamanho do jogo.", -- draft
	["Padding"] = "Espaçamento", -- draft
	["The room between the bar's buttons."] = "O espaço entre os botões da barra.", -- draft
	["The Bar's Shape"] = "O formato da barra", -- draft
	["The bar as the rows above lay it out. Saved into your Edit Mode layout when you let a slider go (in a fight, when it ends); the bar itself changes after a reload."] = "A barra como as linhas acima a dispõem. Salva no seu layout do Modo de edição ao soltar um controle deslizante (em combate, quando ele termina); a barra em si muda após recarregar.", -- draft
	["Buff Layout"] = "Layout dos bônus", -- draft
	["The size of your buff and debuff icons, in pixels: MelloUI's own rows while Your Buffs And Debuffs shows them, else the game's buff and debuff bars (saved into your Edit Mode layout in its own steps of 3 pixels, shown after a reload; 30 is the game's size)."] = "O tamanho dos seus ícones de bônus e penalidades, em pixels: as fileiras do MelloUI enquanto Seus bônus e penalidades as mostra; senão, as barras de bônus e penalidades do jogo (salvo no seu layout do Modo de edição em passos de 3 pixels, visível após recarregar; 30 é o tamanho do jogo).", -- draft
	["Spacing"] = "Espaçamento", -- draft
	["The room between your buff and debuff icons."] = "O espaço entre seus ícones de bônus e penalidades.", -- draft
	["Per Row"] = "Por fileira", -- draft
	["How many buffs stand in a row before the next row starts. Your debuffs start a row of their own (the game's debuff bar takes at most 16 in a row)."] = "Quantos bônus cabem numa fileira antes da próxima começar. Suas penalidades começam uma fileira própria (a barra de penalidades do jogo aceita no máximo 16 por fileira).", -- draft
	["Grow"] = "Crescer", -- draft
	["Which way a row of buffs grows from the first one."] = "Para que lado uma fileira de bônus cresce a partir do primeiro.", -- draft
	["New Rows"] = "Novas fileiras", -- draft
	["Where the next row of buffs goes: under the first, or over it."] = "Onde vai a próxima fileira de bônus: abaixo da primeira ou acima dela.", -- draft
	["Down"] = "Baixo", -- draft
	["Up"] = "Cima", -- draft
	["Split Stack"] = "Dividir pilha", -- draft
	["Mouse Wheel Amount"] = "Quantidade pela roda do mouse", -- draft
	["In the box that splits a stack (Shift-click a stack), the mouse wheel changes the amount: up adds one, down takes one, ten at a time while you hold Shift."] = "Na caixa que divide uma pilha (Shift-clique numa pilha), a roda do mouse muda a quantidade: para cima soma um, para baixo tira um, dez de cada vez segurando Shift.", -- draft
	["Half Button"] = "Botão de metade", -- draft
	["A ½ button at the left end of the split box's amount: click it and the amount is half the stack (191 makes 95). Buying in bundles at a merchant, it rounds down to whole bundles."] = "Um botão ½ na ponta esquerda da quantidade da caixa de divisão: clique e a quantidade vira metade da pilha (191 dá 95). Comprando em lotes num mercador, arredonda para baixo em lotes inteiros.", -- draft
	["Item Slots"] = "Compartimentos de itens", -- draft
	["Quality Gems"] = "Gemas de qualidade", -- draft
	["A small gem in the top-left corner of every item in your bags, the bank and the guild bank, in the colour of the item's quality: grey for junk, white for common, then green, blue, purple and orange. Junk and better items stand out at a glance. While the game shows its own mark in that corner (the junk coin at a merchant, the upgrade arrow, the exclamation mark on an item that starts a quest, the quality badge on a crafting reagent), the gem moves to the top-right corner. One switch for all three windows."] = "Uma pequena gema no canto superior esquerdo de cada item nas suas bolsas, no banco e no banco da guilda, na cor da qualidade do item: cinza para sucata, branco para comum, depois verde, azul, roxo e laranja. A sucata e os melhores itens se destacam num relance. Enquanto o jogo mostra a própria marca nesse canto (a moeda de sucata num mercador, a seta de melhoria, a exclamação de um item que inicia uma missão, o selo de qualidade de um reagente de criação), a gema vai para o canto superior direito. Um interruptor para as três janelas.", -- draft
	["Grey Out Junk"] = "Acinzentar sucata", -- draft
	["Junk (grey quality) items show grey in your bags, the bank and the guild bank, so they stand apart from what you keep. One switch for all three windows."] = "Itens de sucata (qualidade cinza) aparecem em cinza nas suas bolsas, no banco e no banco da guilda, para se destacarem do que você guarda. Um interruptor para as três janelas.", -- draft
	["Level Up"] = "Subir de nível", -- draft
	["When you gain a level, a light runs along the experience bar and the on-screen notice says your new level and, with the Quest List, how many quests it opened in your zone (their givers pop onto the world map the next time it shows them). With the painted reskin, the number in your player frame's level circle also turns over with a ring of light. Not with Reduce Motion: then only the notice."] = "Quando você sobe de nível, uma luz percorre a barra de experiência e o aviso na tela diz o seu novo nível e, com a Lista de missões, quantas missões ele abriu na sua zona (quem as dá aparece no mapa-múndi na próxima vez que ele os mostrar). Com o visual pintado, o número no círculo de nível da sua janela do jogador também gira com um anel de luz. Não com Reduzir movimento: aí só o aviso.", -- draft
	["XP Gain"] = "Ganho de experiência", -- draft
	["When you gain experience, the stretch of the experience bar just gained lights up while a light runs along it to the new end. Not with Reduce Motion."] = "Quando você ganha experiência, o trecho da barra de experiência recém-ganho se ilumina enquanto uma luz a percorre até o novo fim. Não com Reduzir movimento.", -- draft
	-- Stats
	["Small coloured FPS and latency readout in the bottom right corner."] = "Pequeno indicador colorido de FPS e latência no canto inferior direito.", -- draft
	["Frames per second and latency in the corner. Blame the server with confidence."] = "Quadros por segundo e latência no canto. Culpe o servidor com confiança.", -- draft
	["Values"] = "Valores", -- draft
	["Show FPS"] = "Mostrar FPS", -- draft
	["Frames per second."] = "Quadros por segundo.", -- draft
	["Show Latency"] = "Mostrar latência", -- draft
	["Home latency in milliseconds."] = "Latência local em milissegundos.", -- draft
	["Show World Latency Too"] = "Mostrar também a latência do mundo", -- draft
	["Also show the world server latency next to the home latency."] = "Também mostra a latência do servidor do mundo ao lado da latência local.", -- draft
	["Look"] = "Visual", -- draft
	["Distance from the right edge of the screen."] = "Distância da borda direita da tela.", -- draft
	["Distance from the bottom edge of the screen."] = "Distância da borda inferior da tela.", -- draft
	["Update Interval"] = "Intervalo de atualização", -- draft
	-- Vendor
	["Vendor"] = "Mercador", -- draft
	["Automatically repair your gear and sell junk items when visiting a merchant."] = "Conserta seu equipamento e vende sucata automaticamente ao visitar um mercador.", -- draft
	["Sell the grey, mend the steel. Every merchant visit handled before the window opens."] = "Venda o cinza, conserte o aço. Cada visita ao mercador resolvida antes de a janela abrir.", -- draft
	["Repair"] = "Conserto", -- draft
	["Auto Repair"] = "Conserto automático", -- draft
	["Repair all equipped and carried items when a merchant that can repair is opened."] = "Conserta todos os itens equipados e carregados ao abrir um mercador que conserte.", -- draft
	["Use Guild Funds"] = "Usar fundos da guilda", -- draft
	["Pay repairs from the guild bank when allowed. Falls back to your own gold if the guild cannot cover the cost."] = "Paga os consertos com o banco da guilda quando permitido. Usa o seu próprio ouro se a guilda não puder cobrir o custo.", -- draft
	["Selling"] = "Venda", -- draft
	["Auto Sell Junk"] = "Vender sucata automaticamente", -- draft
	["Sell all grey quality items in your bags when a merchant is opened."] = "Vende todos os itens de qualidade cinza das suas bolsas ao abrir um mercador.", -- draft
	["Report In Chat"] = "Relatar no bate-papo", -- draft
	["Print the repair cost, the gold gained from selling junk and what Restock bought for you."] = "Escreve o custo do conserto, o ouro ganho vendendo sucata e o que Reabastecer comprou para você.", -- draft
	-- Services
	["Services"] = "Serviços", -- draft
	["Service icons under the minimap that route you to the nearest repair, mailbox, innkeeper, flight master, auction house, bank, trainer, barber or transmogrifier."] = "Ícones de serviço sob o minimapa que levam você ao conserto, caixa de correio, estalajadeiro, mestre de voo, casa de leilões, banco, instrutor, barbeiro ou transmogrificador mais próximo.", -- draft
	["Repair, mailbox, innkeeper, bank... the nearest one is a click under the minimap."] = "Conserto, caixa de correio, estalajadeiro, banco... o mais próximo está a um clique sob o minimapa.", -- draft
	["Icon Bar Under The Minimap"] = "Barra de ícones sob o minimapa", -- draft
	["Service buttons under the minimap; they move with the minimap in Edit Mode. Groups: one row of group buttons as wide as the map; click one to open its services with their distances, then click a service to route to the nearest one by road. All Buttons: two rows with an icon for every service; click one to route there. Right-click stops the route. A grey button has none known on this continent yet. With the square minimap and \"Merge With Services\" on (the Minimap page, Services), the buttons sit inside the minimap's frame."] = "Botões de serviço sob o minimapa; eles se movem com o minimapa no Modo de edição. Grupos: uma fileira de botões de grupo da largura do mapa; clique num para abrir seus serviços com as distâncias, depois clique num serviço para uma rota pela estrada até o mais próximo. Todos os botões: duas fileiras com um ícone por serviço; clique num para uma rota. O clique direito interrompe a rota. Um botão cinza ainda não conhece nenhum neste continente. Com o minimapa quadrado e \"Unir aos serviços\" ligado (página Minimapa, Serviços), os botões ficam dentro da moldura do minimapa.", -- draft
	["Button Layout"] = "Layout dos botões", -- draft
	["Groups: one row of buttons as wide as the map (Travel, Trade, Repair, Trainers, Looks, Errands, and AddOns while your addons have minimap buttons). Click a group for a small list of its services, each with the distance to the nearest one; click a service to route there. Repair routes at once. Errands lists your reminders (Restock, Mail, Repair Gear, Trainer) and how each stands; click one to route to the nearest place for it. All Buttons: two rows with an icon for every service."] = "Grupos: uma fileira de botões da largura do mapa (Viagem, Comércio, Conserto, Instrutores, Visuais, Tarefas, e AddOns enquanto seus addons tiverem botões no minimapa). Clique num grupo para uma pequena lista dos seus serviços, cada um com a distância até o mais próximo; clique num serviço para uma rota. Conserto traça a rota na hora. Tarefas lista seus lembretes (Reabastecer, Correio, Consertar equipamento, Instrutor) e a situação de cada um; clique num para uma rota até o lugar mais próximo. Todos os botões: duas fileiras com um ícone por serviço.", -- draft
	["Groups"] = "Grupos", -- draft
	["All Buttons"] = "Todos os botões", -- draft
	["AddOns Group"] = "Grupo AddOns", -- draft
	["Your addons' minimap buttons (Questie and the others that put a round button on the minimap's edge) taken off the minimap and gathered into one more group in the Services row, AddOns: click it for a list of them. A click on an addon there is that addon's own (left, right or middle), and pointing at it shows its own tooltip. Only with Button Layout's Groups. Off: the buttons go back on the minimap."] = "Os botões de minimapa dos seus addons (Questie e os outros que põem um botão redondo na borda do minimapa) tirados do minimapa e reunidos em mais um grupo na fileira Serviços, AddOns: clique nele para a lista. Um clique num addon ali é o do próprio addon (esquerdo, direito ou do meio), e apontar para ele mostra a dica dele. Só com os Grupos do Layout dos botões. Desligado: os botões voltam ao minimapa.", -- draft
	["Bar Distance From The Minimap"] = "Distância da barra ao minimapa", -- draft
	["How far under the minimap the buttons sit. Not used while they are merged into the square minimap's frame."] = "A que distância sob o minimapa os botões ficam. Não usado enquanto estão unidos à moldura do minimapa quadrado.", -- draft
	["Round Icons"] = "Ícones redondos", -- draft
	["Show the service icons as round medallions in a round rim instead of squares."] = "Mostra os ícones de serviço como medalhões redondos num aro redondo em vez de quadrados.", -- draft
	["Trays Slide Out"] = "As bandejas deslizam", -- draft
	["A group's list slides out from the minimap column like a drawer when you click its button, its rows one after another, and slides back in as it closes. Not with Reduce Motion: then it shows at once."] = "A lista de um grupo desliza para fora da coluna do minimapa como uma gaveta quando você clica no botão dele, as linhas uma após a outra, e volta ao fechar. Não com Reduzir movimento: aí aparece na hora.", -- draft
	["Minimap Button"] = "Botão do minimapa", -- draft
	["Also show a round button on the minimap's edge that opens the list of the nearest services; drag it to move it, right-click it to stop the route. /services opens the same list."] = "Também mostra um botão redondo na borda do minimapa que abre a lista dos serviços mais próximos; arraste-o para movê-lo, clique direito para parar a rota. /services abre a mesma lista.", -- draft
	-- Reminders
	["Reminders"] = "Lembretes", -- draft
	["A round button by your portrait for errands: supplies low (Restock), new mail, gear to repair, a trainer with something new. Click it to route there. Off, none of the four shows; the Widgets' portrait reminders keep their own switches."] = "Um botão redondo junto ao seu retrato para tarefas: suprimentos baixos (Reabastecer), carta nova, equipamento para consertar, um instrutor com novidade. Clique para traçar a rota. Desligado, nenhum dos quatro aparece; os lembretes de retrato dos Widgets mantêm seus próprios interruptores.", -- draft
	["Supplies, mail, repairs and training: a gentle nudge beside your portrait, never a nag."] = "Suprimentos, correio, consertos e treinamento: um toque gentil junto ao seu retrato, nunca uma cobrança.", -- draft
	["New Mail"] = "Carta nova", -- draft
	["Remind you when mail is waiting for you. It goes once you open a mailbox, and comes back only for mail that arrives after."] = "Lembra quando há carta esperando por você. Some quando você abre uma caixa de correio e só volta por cartas que chegarem depois.", -- draft
	["Repair Gear"] = "Consertar equipamento", -- draft
	["Remind you when your gear is wearing out. Broken gear goes to the top of the list."] = "Lembra quando seu equipamento está se desgastando. Equipamento quebrado vai para o topo da lista.", -- draft
	["Remind At"] = "Lembrar em", -- draft
	["Remind you once your most worn piece of gear is down to this much durability."] = "Lembra assim que a peça de equipamento mais gasta cai para esta durabilidade.", -- draft
	["Trainer"] = "Instrutor", -- draft
	["Remind you when a trainer has something new for you."] = "Lembra quando um instrutor tem algo novo para você.", -- draft
	["Class Spells"] = "Feitiços de classe", -- draft
	["When you reach a level with new spells at your class trainer. It stays until you have learned them; each visit to your class trainer tells MelloUI when the next ones come, and before your first visit it goes by the levels trainers teach at."] = "Quando você chega a um nível com feitiços novos no seu instrutor de classe. Fica até você aprendê-los; cada visita ao seu instrutor de classe diz ao MelloUI quando vêm os próximos, e antes da sua primeira visita ele se guia pelos níveis em que os instrutores ensinam.", -- draft
	["Profession Ranks"] = "Níveis de profissão", -- draft
	["When one of your professions can learn its next rank at a trainer: Journeyman, Expert or Artisan."] = "Quando uma das suas profissões pode aprender o próximo nível com um instrutor: Profissional, Perito ou Artífice.", -- draft
	["Stay Up In Rest Areas"] = "Manter em áreas de descanso", -- draft
	["In an inn or a city, and in a town like Sentinel Hill, every reminder stays until it is done (a mailbox opened, the spells or the rank learned ...) or you leave; Not now there waits until you next enter one."] = "Numa estalagem ou cidade, e num povoado como Morro da Sentinela, cada lembrete fica até ser resolvido (uma caixa de correio aberta, os feitiços ou o nível aprendidos ...) ou até você sair; Agora não ali espera até você entrar numa de novo.", -- draft
	["Widget"] = "Widget", -- draft
	["Place"] = "Lugar", -- draft
	["Where the reminder button sits beside your portrait. With the player frame hidden it keeps a place of its own, which you can move in Edit Layout."] = "Onde o botão de lembrete fica junto ao seu retrato. Com a janela do jogador escondida, ele mantém um lugar próprio, que você pode mover em Editar layout.", -- draft
	["Left of the portrait"] = "À esquerda do retrato", -- draft
	["Above the portrait"] = "Acima do retrato", -- draft
	["Right of the portrait"] = "À direita do retrato", -- draft
	["Glow"] = "Brilho", -- draft
	["The soft glow around the button: a gentle pulse for a few seconds, then steady; always steady; or none. It brightens when you are close to where the reminder sends you."] = "O brilho suave ao redor do botão: um pulso suave por alguns segundos, depois fixo; sempre fixo; ou nenhum. Ele se intensifica quando você está perto de onde o lembrete manda você.", -- draft
	["Pulse, then steady"] = "Pulso, depois fixo", -- draft
	["Steady"] = "Fixo", -- draft
	["Show For"] = "Mostrar por", -- draft
	["How long a new reminder stays before it tucks itself away. It stays while your pointer is on it."] = "Quanto tempo um lembrete novo fica antes de se recolher. Fica enquanto o ponteiro está sobre ele.", -- draft
	["Lock The Widgets"] = "Travar os widgets", -- draft
	["Keep the widget column (Voice Over, loot rolls, the corpse run and the rest) where it is: Edit Layout shows its plate but does not move it. Voice Over's padlock sets this too."] = "Mantém a coluna de widgets (Voice Over, rolagens de saque, a corrida até o corpo e o resto) onde está: Editar layout mostra a placa dela, mas não a move. O cadeado do Voice Over também define isto.", -- draft
	["Most Widgets Shown"] = "Máximo de widgets visíveis", -- draft
	["How many widgets the column shows at once. The rest wait in a slim \"+2 more\" row on top; a click there lists them. Loot rolls, summons, resurrect offers and ready checks always show, and Voice Over keeps the bottom place."] = "Quantos widgets a coluna mostra de uma vez. O resto espera numa fileira fina \"+2 mais\" no topo; um clique os lista. Rolagens de saque, invocações, ofertas de ressurreição e verificações de prontidão sempre aparecem, e o Voice Over mantém o lugar de baixo.", -- draft
	-- Restock
	["Restock"] = "Reabastecer", -- draft
	["Keeps drink, food, ammunition and reagents in your bags: a reminder when one runs low (with Reminders on), and at a shop a list of what to buy, bought only when you click Buy."] = "Mantém bebida, comida, munição e reagentes nas suas bolsas: um lembrete quando algo acaba (com Lembretes ligado) e, numa loja, uma lista do que comprar, comprado só quando você clica em Comprar.", -- draft
	["Water, bread and arrows, topped up before they run out."] = "Água, pão e flechas, repostos antes de acabarem.", -- draft
	["Remind Below"] = "Lembrar abaixo de", -- draft
	["You are reminded when a line drops below this share of its amount: at 50 %, a line of 20 water reminds you at 9. At a shop it is bought back up to the full amount. The reminder needs Reminders on; the Restock List marks the low lines either way."] = "Você é lembrado quando uma linha cai abaixo desta parte da quantidade: a 50 %, uma linha de 20 águas lembra você em 9. Numa loja, ela é recomprada até a quantidade cheia. O lembrete precisa de Lembretes ligado; a Lista de reabastecimento marca as linhas baixas de qualquer forma.", -- draft
	["Shopping List At The Shop"] = "Lista de compras na loja", -- draft
	["At a merchant who sells what you are low on, a small list beside the shop window: each item, how many and the price, and the total. Nothing is bought until you click Buy."] = "Num mercador que vende o que está faltando, uma pequena lista ao lado da janela da loja: cada item, quantos e o preço, e o total. Nada é comprado até você clicar em Comprar.", -- draft
	["Restock List"] = "Lista de reabastecimento", -- draft
	["What to keep in your bags and how many. Each character has its own list; a new one starts with suggestions for its class. Also /restock."] = "O que manter nas suas bolsas e quanto. Cada personagem tem sua própria lista; uma nova começa com sugestões para a classe. Também /restock.", -- draft
	["Edit"] = "Editar", -- draft
	-- Widgets
	["Widgets"] = "Widgets", -- draft
	["Small live widgets in one column: loot rolls, the way back to your corpse, timed quests, summons, resurrect offers, ready checks, whispers, your pet, the auction house, crafting batches, profession cooldowns, quest items and a healer drinking. And more reminders by your portrait: bags, talents, Well Fed, weapon poisons and oils, your buffs."] = "Pequenos widgets ao vivo numa coluna: rolagens de saque, o caminho de volta ao seu corpo, missões com tempo, invocações, ofertas de ressurreição, verificações de prontidão, sussurros, seu ajudante, a casa de leilões, lotes de criação, recargas de profissão, itens de missão e um curador bebendo. E mais lembretes junto ao seu retrato: bolsas, talentos, Bem Alimentado, venenos e óleos de arma, seus bônus.", -- draft
	["What needs you now, in one small column."] = "O que precisa de você agora, numa pequena coluna.", -- draft
	["In The Column"] = "Na coluna", -- draft
	["Loot Rolls"] = "Rolagens de saque", -- draft
	["A roll in a group: the item in its quality colour, a ring for the time left, and Need, Greed and Pass on hover. The count is the rolls waiting. The game's own roll window stays out of sight meanwhile (with the Gamepad UI it stays)."] = "Uma rolagem em grupo: o item na cor da qualidade, um anel para o tempo restante e Necessidade, Ganância e Passar ao passar o mouse. O número é o de rolagens esperando. A janela de rolagem do jogo fica escondida enquanto isso (com a interface de controle ela fica).", -- draft
	["Corpse Run"] = "Corrida até o corpo", -- draft
	["As a ghost: how far your body is and which way, and a ring until you can come back. Click it for the way there; at your body, Resurrect. The game's own Resurrect popup is see-through and click-through meanwhile."] = "Como fantasma: a que distância está o seu corpo e em que direção, e um anel até você poder voltar. Clique para ver o caminho; junto ao corpo, Ressuscitar. A janela Ressuscitar do jogo fica transparente e deixa os cliques passarem enquanto isso.", -- draft
	["Timed Quests"] = "Missões com tempo", -- draft
	["A quest with a time limit: a ring for its whole time and the time left."] = "Uma missão com limite de tempo: um anel para todo o tempo e o tempo restante.", -- draft
	["Summons"] = "Invocações", -- draft
	["Someone summons you: where to, the time left, and Accept or Decline on hover. The game's own popup is see-through and click-through meanwhile."] = "Alguém invoca você: para onde, o tempo restante e Aceitar ou Recusar ao passar o mouse. A janela do jogo fica transparente e deixa os cliques passarem enquanto isso.", -- draft
	["Resurrect Offers"] = "Ofertas de ressurreição", -- draft
	["Someone offers to resurrect you: the time left, and Accept or Decline on hover. The game's own popup is see-through and click-through meanwhile."] = "Alguém se oferece para ressuscitar você: o tempo restante e Aceitar ou Recusar ao passar o mouse. A janela do jogo fica transparente e deixa os cliques passarem enquanto isso.", -- draft
	["Ready Checks"] = "Verificações de prontidão", -- draft
	["The leader's ready check and its time, with Ready and Not Ready on hover (a click on it: Ready). The game's own box stays away meanwhile (with the Gamepad UI it stays); its alert sound and the taskbar flash still come."] = "A verificação de prontidão do líder e o tempo dela, com Pronto e Ainda não. ao passar o mouse (um clique nela: Pronto). A caixa do jogo fica afastada enquanto isso (com a interface de controle ela fica); o som de alerta e o pisca da barra de tarefas ainda vêm.", -- draft
	["Threat"] = "Ameaça", -- draft
	["In a group fight, only when it matters: close to pulling your target (\"Ease off\") or with it on you (\"Aggro\"), and for a tank the mobs not on you. The ring is your threat against the pull; point at it for the group's threat on your target."] = "Numa luta em grupo, só quando importa: perto de puxar o seu alvo (\"Pega leve\") ou com ele em você (\"Aggro\"), e para um tanque os monstros que não estão nele. O anel é a sua ameaça contra o limite; aponte para ver a ameaça do grupo no seu alvo.", -- draft
	["Whispers"] = "Sussurros", -- draft
	["A new whisper: the sender in their class colour, the last line and how many are unread. Reply opens their whisper window. Needs Chat's Whisper Popup Window."] = "Um sussurro novo: o remetente na cor da classe, a última linha e quantos não foram lidos. Responder abre a janela de sussurro dele. Precisa da Janela de sussurro do bate-papo.", -- draft
	["Hunter Pet"] = "Ajudante do caçador", -- draft
	["Your pet is not happy: its face, a ring for its happiness, and Feed Pet on hover (out of combat)."] = "Seu ajudante não está feliz: o rosto dele, um anel para a felicidade e Alimentar Ajudante ao passar o mouse (fora de combate).", -- draft
	["Auction House"] = "Casa de leilões", -- draft
	["Outbid, sold, won and expired at the auction house, in one list. Click it for the way to the nearest mailbox."] = "Lance superado, vendido, arrematado e expirado na casa de leilões, numa lista. Clique para o caminho até a caixa de correio mais próxima.", -- draft
	["Crafting"] = "Criação", -- draft
	["A batch you craft: which one of how many, a ring for each item, and Stop on hover."] = "Um lote que você cria: qual de quantos, um anel para cada item e Parar ao passar o mouse.", -- draft
	["Profession Cooldowns"] = "Recargas de profissão", -- draft
	["A profession cooldown ready again (a transmute, mooncloth, the salt shaker). MelloUI learns it when you open that profession."] = "Uma recarga de profissão pronta de novo (uma transmutação, o tecido lunar, o saleiro). O MelloUI aprende ao abrir aquela profissão.", -- draft
	["Quest Items"] = "Itens de missão", -- draft
	["In a quest's objective area, with the quest's item in your bags: the item, a ring for the objective's progress and how many you carry. Click it to use the item (out of combat: it folds away in a fight)."] = "Na área do objetivo de uma missão, com o item da missão nas suas bolsas: o item, um anel para o progresso do objetivo e quantos você carrega. Clique para usar o item (fora de combate: ele se recolhe numa luta).", -- draft
	["Healer Drinking"] = "Curador bebendo", -- draft
	["When you tank a group, between pulls: a healer of your group is drinking, so wait before the next pull. It goes when they stop or a fight starts. The game keeps party mana hidden from addons, so it shows their drinking, not their mana."] = "Quando você tanqueia um grupo, entre puxadas: um curador do seu grupo está bebendo, então espere antes da próxima. Some quando ele para ou uma luta começa. O jogo esconde a mana do grupo dos addons, então mostra que ele bebe, não a mana.", -- draft
	["Rare Alert"] = "Alerta de raro", -- draft
	["A rare or rare elite nearby, seen on the minimap, as a nameplate, as your target or under the mouse: its face, its name and how far it is, glowing as it comes up. Click its face to target it (out of combat); Lead Me There shows the way to where the minimap has it."] = "Um raro ou elite raro por perto, visto no minimapa, como placa de identificação, como seu alvo ou sob o mouse: o rosto, o nome e a distância, brilhando ao aparecer. Clique no rosto para selecioná-lo (fora de combate); Me leve até lá mostra o caminho até onde o minimapa o indica.", -- draft
	["Rare Alert Sound"] = "Som do alerta de raro", -- draft
	["Play a sound when a rare is spotted."] = "Toca um som quando um raro é avistado.", -- draft
	["By The Portrait"] = "Junto ao retrato", -- draft
	["Bags Almost Full"] = "Bolsas quase cheias", -- draft
	["Remind you when your bags are almost full; it stays, in a fight too, until you make room. Click it for the way to the nearest vendor."] = "Lembra quando suas bolsas estão quase cheias; fica, em luta também, até você liberar espaço. Clique para o caminho até o comerciante mais próximo.", -- draft
	["Free Slots"] = "Espaços livres", -- draft
	["Remind you once this many free bag slots or fewer are left."] = "Lembra assim que restarem esta quantidade de espaços livres ou menos.", -- draft
	["Talent Points"] = "Pontos de talento", -- draft
	["Remind you when you have talent points to spend."] = "Lembra quando você tem pontos de talento para gastar.", -- draft
	["Well Fed Ending"] = "Fim do Bem Alimentado", -- draft
	["Remind you when Well Fed has two minutes left."] = "Lembra quando restam dois minutos de Bem Alimentado.", -- draft
	["Weapon Poisons & Oils"] = "Venenos e óleos de arma", -- draft
	["Remind you when a poison, an oil or a sharpening stone has run out on a weapon, or has two minutes left, while you carry one to put it back on. It stays until it is back on, in fights too; click it to put it back on (out of combat)."] = "Lembra quando um veneno, óleo ou pedra de amolar acabou numa arma, ou faltam dois minutos, enquanto você carrega um para repor. Fica até estar reposto, em lutas também; clique para repor (fora de combate).", -- draft
	["Your Buffs"] = "Seus bônus", -- draft
	["Remind you when one of your own buffs is missing on you: Arcane Intellect and a mage's armor, Fortitude, Inner Fire and Divine Spirit, Mark of the Wild, a warlock's armor. Only buffs you can cast. It stays until the buff is back, in fights too (the game hides buffs in a fight, so one lost there shows after it); click it to cast (out of combat)."] = "Lembra quando falta em você um dos seus próprios bônus: Intelecto Arcano e a armadura de um mago, Fortitude, Fogo Interior e Espírito Divino, Marca do Indomado, a armadura de um bruxo. Só bônus que você pode lançar. Fica até o bônus voltar, em lutas também (o jogo esconde bônus em luta, então um perdido ali aparece depois); clique para lançar (fora de combate).", -- draft
	["Your Buffs On The Group"] = "Seus bônus no grupo", -- draft
	["Remind you when people in your group are missing a buff you can cast (Arcane Intellect and Divine Spirit only on those who use mana); point at it for their names. It stays until they have it, in fights too; click it to cast it on them, one by one (out of combat)."] = "Lembra quando pessoas do seu grupo estão sem um bônus que você pode lançar (Intelecto Arcano e Espírito Divino só em quem usa mana); aponte para ver os nomes. Fica até que tenham, em lutas também; clique para lançar neles, um por um (fora de combate).", -- draft
	-- Discard
	["Discard"] = "Descartar", -- draft
	["A button on the bag and loot windows that throws away your cheapest grey or white junk to free a slot (sells it at a vendor)."] = "Um botão nas janelas de bolsa e de saque que joga fora sua sucata cinza ou branca mais barata para liberar um espaço (vende num comerciante).", -- draft
	["Full bags? The cheapest junk makes room, never anything worth keeping."] = "Bolsas cheias? A sucata mais barata abre espaço, nunca algo que valha guardar.", -- draft
	["Discard Button"] = "Botão Descartar", -- draft
	["A button on the bag window that frees a slot: it throws away the grey or white junk item worth least (at a vendor it sells it). Never food, drink, potions, scrolls, conjured items, crafting materials, quest items, reagents, ammunition, keys, white gear or anything on your Restock list. A white item asks first."] = "Um botão na janela de bolsa que libera um espaço: joga fora o item de sucata cinza ou branco que vale menos (num comerciante, vende). Nunca comida, bebida, poções, pergaminhos, itens conjurados, materiais de criação, itens de missão, reagentes, munição, chaves, equipamento branco nem nada da sua lista Reabastecer. Um item branco pergunta antes.", -- draft
	["Discard Button On Loot"] = "Botão Descartar no saque", -- draft
	["The same button on the loot window. It frees a slot only when something you are looting is worth more than what it would throw away."] = "O mesmo botão na janela de saque. Só libera um espaço quando algo que você está saqueando vale mais do que o que seria jogado fora.", -- draft
	["Never Throw Away Items Worth"] = "Nunca jogar fora itens que valem", -- draft
	["In silver: a stack worth this or more is never thrown away (selling it at a vendor still is). 100 silver = 1 gold."] = "Em prata: uma pilha que vale isto ou mais nunca é jogada fora (vendê-la num comerciante, sim). 100 de prata = 1 de ouro.", -- draft
	-- Gains
	["Gains"] = "Ganhos", -- draft
	["Short lines beside your character show what you just gained: a skill point, the items you loot or receive, and what you buy. You can move them in Edit Layout."] = "Linhas curtas ao lado do seu personagem mostram o que você acabou de ganhar: um ponto de perícia, os itens que você saqueia ou recebe e o que compra. Você pode movê-las em Editar layout.", -- draft
	["Every skill point and every new item, told softly beside your character, then gone."] = "Cada ponto de perícia e cada item novo, contados com suavidade ao lado do seu personagem, e depois somem.", -- draft
	["Show"] = "Mostrar", -- draft
	["Skill Ups"] = "Aumentos de perícia", -- draft
	["A line when one of your skills goes up: weapon skills, Defense, professions, secondary skills and languages."] = "Uma linha quando uma das suas perícias sobe: perícias de arma, Defesa, profissões, perícias secundárias e idiomas.", -- draft
	["Show Skill Values"] = "Mostrar valores de perícia", -- draft
	["The skill's new value and its cap after its name, such as 57 / 80."] = "O novo valor da perícia e o teto depois do nome, como 57 / 80.", -- draft
	["Looted & Received Items"] = "Itens saqueados e recebidos", -- draft
	["A line for each item that comes into your bags: loot, quest rewards, crafted items, mail and trades. Moving items between your bags, the bank and your gear never counts."] = "Uma linha para cada item que entra nas suas bolsas: saque, recompensas de missão, itens criados, correio e negociações. Mover itens entre suas bolsas, o banco e seu equipamento nunca conta.", -- draft
	["Bought Items"] = "Itens comprados", -- draft
	["A line for what you buy from a merchant, buybacks too, marked as bought."] = "Uma linha para o que você compra de um mercador, recompras também, marcada como comprada.", -- draft
	["Junk Items"] = "Sucata", -- draft
	["Also show junk (grey) items. Off: they are left out."] = "Também mostra sucata (cinza). Desligado: fica de fora.", -- draft
	["Money"] = "Dinheiro", -- draft
	["A line when your money goes up: loot, quest rewards, sales, mail and trades, with the game's coins. Several gains in a row add up on one line. Spending makes no line."] = "Uma linha quando o seu dinheiro sobe: saque, recompensas de missão, vendas, correio e negociações, com as moedas do jogo. Vários ganhos seguidos somam numa linha. Gastar não cria linha.", -- draft
	["Currencies"] = "Moedas", -- draft
	["A line for the other currencies you gain (honor, tokens, marks), with the currency's own icon."] = "Uma linha para as outras moedas que você ganha (honra, fichas, marcas), com o ícone da moeda.", -- draft
	["Item Names In Quality Colour"] = "Nomes de itens na cor da qualidade", -- draft
	["Item names in their quality colour (green, blue, purple) beside the quality gem. Blue and purple read less well over bright ground. Off: the names in the text colour."] = "Nomes de itens na cor da qualidade (verde, azul, roxo) ao lado da gema de qualidade. Azul e roxo leem menos bem sobre fundo claro. Desligado: os nomes na cor do texto.", -- draft
	["Lines"] = "Linhas", -- draft
	["How long each line stays before it fades. Gaining the same skill or item again adds to its line and starts it over."] = "Quanto tempo cada linha fica antes de sumir. Ganhar de novo a mesma perícia ou item soma à linha dele e a reinicia.", -- draft
	-- Meter
	["Damage Meter"] = "Medidor de dano", -- draft
	["MelloUI's damage meter in place of the game's: three numbers by every frame (this fight, this run, healing), a race bar for the group in a fight, a summary after it and a Fight History window. The game's own damage meter is switched off while it is on, and comes back as you had it when it is off."] = "O medidor de dano do MelloUI no lugar do do jogo: três números em cada quadro (esta luta, esta incursão, cura), uma barra de corrida para o grupo numa luta, um resumo depois e uma janela de Histórico de lutas. O medidor do jogo é desligado enquanto este está ligado e volta como você o tinha quando este é desligado.", -- draft
	["How the fight went, where you already look."] = "Como foi a luta, onde você já está olhando.", -- draft
	["Your Values"] = "Seus valores", -- draft
	["Three numbers on top of your frame: the sword this fight's damage per second, the hourglass this run's, the cross your healing per second. Live in a fight, the last fight's after it. Move them in Edit Layout (Your Values)."] = "Três números em cima do seu quadro: a espada o dano por segundo desta luta, a ampulheta o desta incursão, a cruz sua cura por segundo. Ao vivo numa luta, os da última luta depois. Mova-os em Editar layout (Seus valores).", -- draft
	["Party Values"] = "Valores do grupo", -- draft
	["The same three numbers on top of each party frame. To make room, the game's own Show Party Pets setting is switched on while this is on (the party frames stand a little further apart, and party pets show under them); your own setting comes back when it is off. With raid-style party frames: On Raid-Style Frames."] = "Os mesmos três números em cima de cada quadro de grupo. Para abrir espaço, a configuração Mostrar ajudantes do grupo do jogo é ligada enquanto isto está ligado (os quadros de grupo ficam um pouco mais afastados e os ajudantes do grupo aparecem embaixo); sua própria configuração volta quando isto é desligado. Com quadros de grupo no estilo de raide: Nos quadros estilo raide.", -- draft
	["On Raid-Style Frames"] = "Nos quadros estilo raide", -- draft
	["A small DPS or healing number on the right of each raid-style or raid frame, beside the health. In a fight, players MelloUI cannot tell apart stay empty until it ends. Point at a frame for all three numbers."] = "Um pequeno número de DPS ou cura à direita de cada quadro estilo raide ou de raide, ao lado da vida. Numa luta, jogadores que o MelloUI não consegue distinguir ficam vazios até ela acabar. Aponte para um quadro para ver os três números.", -- draft
	["Race Bar"] = "Barra de corrida", -- draft
	["In a fight, one line for the group: the top player at its right end with their value, everyone else a class icon at their share of the top, you the bigger icon with the line filled up to you in your class colour. It fades in when the fight starts and out when it ends. The pointer on it lists everyone. Move it in Edit Layout."] = "Numa luta, uma linha para o grupo: o melhor jogador na ponta direita com o valor dele, todos os outros um ícone de classe na sua fração do melhor, você o ícone maior com a linha preenchida até você na cor da sua classe. Aparece quando a luta começa e some quando acaba. O ponteiro sobre ela lista todos. Mova-a em Editar layout.", -- draft
	["Race Bar Shows"] = "A barra de corrida mostra", -- draft
	["What the race bar races. Auto: healing while your group role is healer, else damage."] = "O que a barra de corrida compara. Auto: cura enquanto sua função no grupo for curador; senão, dano.", -- draft
	["Auto"] = "Auto", -- draft
	["Damage"] = "Dano", -- draft
	["Healing"] = "Cura", -- draft
	["Race Bar Pins"] = "Marcas da barra de corrida", -- draft
	["The most players on the race bar: the best ones, and always you."] = "O máximo de jogadores na barra de corrida: os melhores, e sempre você.", -- draft
	["Race Bar Width"] = "Largura da barra de corrida", -- draft
	["How wide the race bar is. Also in Edit Layout: right-click the race bar."] = "A largura da barra de corrida. Também em Editar layout: clique direito na barra de corrida.", -- draft
	["Race Bar Thickness"] = "Espessura da barra de corrida", -- draft
	["How thick your share is on the race bar's line (its pins and labels keep their size). Also in Edit Layout: right-click the race bar."] = "A espessura da sua parte na linha da barra de corrida (as marcas e rótulos mantêm o tamanho). Também em Editar layout: clique direito na barra de corrida.", -- draft
	["Fight Summary"] = "Resumo da luta", -- draft
	["After a fight, for a few seconds in the widget column (longer while you point at it): won or lost and its length, your damage, DPS and rank, the ring your share of the group. The pointer on it shows the top five; a click opens the fight in the Fight History."] = "Depois de uma luta, por alguns segundos na coluna de widgets (mais enquanto você aponta para ele): ganha ou perdida e a duração, seu dano, DPS e posição, o anel sua parte do grupo. O ponteiro sobre ele mostra os cinco melhores; um clique abre a luta no Histórico de lutas.", -- draft
	["Fight History"] = "Histórico de lutas", -- draft
	["The Fight History window: every fight of this session, grouped by run, with the damage, healing and your spells of each. It opens from its button in the chat's button column and from the summary. It takes the place of the game's meter windows."] = "A janela do Histórico de lutas: cada luta desta sessão, agrupada por incursão, com o dano, a cura e seus feitiços de cada uma. Abre pelo botão dela na coluna de botões do bate-papo e pelo resumo. Ocupa o lugar das janelas do medidor do jogo.", -- draft
	["Fights Kept"] = "Lutas guardadas", -- draft
	["How many fights the history keeps, the oldest dropped first. Kept over a /reload; a new login starts it empty."] = "Quantas lutas o histórico guarda; a mais antiga sai primeiro. Guardadas após um /reload; um novo login começa vazio.", -- draft
	-- SwingTimers
	["Swing Timers"] = "Temporizadores de golpe", -- draft
	["A shot bar and a melee bar in MelloUI's look in place of the game's swing timers: each swing and shot counted down beside your weapon's icon, the off hand under the main hand, a wand's shots on the melee bar. The game's own swing timers are switched off while this is on, and come back as you had them when it is off. While the Personal Display shows your swing on its rails (Swing On The Rails), these bars step aside."] = "Uma barra de tiro e uma barra corpo a corpo no visual do MelloUI no lugar dos temporizadores de golpe do jogo: cada golpe e tiro em contagem regressiva ao lado do ícone da sua arma, a mão secundária sob a principal, os tiros de uma varinha na barra corpo a corpo. Os temporizadores do jogo são desligados enquanto isto está ligado e voltam como você os tinha quando desligado. Enquanto a Exibição pessoal mostra seus golpes nos trilhos dela (Golpe nos trilhos), estas barras saem do caminho.", -- draft
	["Every swing and shot at a glance."] = "Cada golpe e tiro num relance.", -- draft
	["Shot Bar"] = "Barra de tiro", -- draft
	["The shot bar for a bow, gun, crossbow or thrown weapon while Auto Shot is on: cream, shrinking to the middle while it reloads (you can move), then red, growing from the middle while you aim: stand still, moving holds the shot back."] = "A barra de tiro para arco, arma de fogo, besta ou arma de arremesso enquanto Tiro Automático está ligado: creme, encolhendo para o meio enquanto recarrega (você pode se mover), depois vermelha, crescendo do meio enquanto você mira: fique parado, mover-se segura o tiro.", -- draft
	["Melee Bar"] = "Barra corpo a corpo", -- draft
	["The melee bar: each swing of your main hand counted down, shrinking to the middle. A wand's shots (Shoot) count down on it too."] = "A barra corpo a corpo: cada golpe da mão principal em contagem regressiva, encolhendo para o meio. Os tiros de uma varinha (Atirar) também contam nela.", -- draft
	["Off Hand Bar"] = "Barra da mão secundária", -- draft
	["A thinner bar under the melee bar for your off-hand weapon's swings, while you carry one."] = "Uma barra mais fina sob a barra corpo a corpo para os golpes da arma da mão secundária, enquanto você carrega uma.", -- draft
	["Seconds"] = "Segundos", -- draft
	["The seconds left, past the bar's right end; on the shot bar Hold and Moving there while you aim. Off: the bars alone."] = "Os segundos restantes, depois da ponta direita da barra; na barra de tiro, Parado e Em movimento ali enquanto você mira. Desligado: só as barras.", -- draft
	["Width"] = "Largura", -- draft
	["How wide the bars are; the weapon's rim hangs left of them and the seconds right of them. Also in Edit Layout (right-click a bar there)."] = "A largura das barras; o aro da arma fica à esquerda delas e os segundos à direita. Também em Editar layout (clique direito numa barra ali).", -- draft
	["Height"] = "Altura", -- draft
	["How tall the bars are; the off hand's is 60 % of it, and the weapon's rim grows with them from 15 on. Also in Edit Layout."] = "A altura das barras; a da mão secundária tem 60 % dela, e o aro da arma cresce com elas a partir de 15. Também em Editar layout.", -- draft
	["In Combat: a bar shows in a fight once it swings or shoots, and fades out when the fight ends (the shot bar also when Auto Shot stops). Always: each bar shows while you carry a weapon for it, at rest between swings."] = "Em combate: uma barra aparece numa luta assim que golpeia ou atira, e some quando a luta acaba (a barra de tiro também quando o Tiro Automático para). Sempre: cada barra aparece enquanto você carrega uma arma para ela, em repouso entre golpes.", -- draft
	["In Combat"] = "Em combate", -- draft
	["Always"] = "Sempre", -- draft
	-- PartyMarkers
	["Party Markers"] = "Marcadores do grupo", -- draft
	["A class medallion above every party member's friendly nameplate, with a ring in their role's colour. In the open world; inside instances the game keeps friendly nameplates to itself."] = "Um medalhão de classe acima da placa de identificação amistosa de cada membro do grupo, com um anel na cor da função. No mundo aberto; dentro de instâncias o jogo reserva para si as placas de identificação amistosas.", -- draft
	["A class medallion over every party member's head, ringed in their role's colour: the healer, found at a glance."] = "Um medalhão de classe sobre a cabeça de cada membro do grupo, com um aro na cor da função: o curador, achado num relance.", -- draft
	["Markers"] = "Marcadores", -- draft
	["Mark"] = "Marcar", -- draft
	["Whose nameplate gets the class medallion above the name."] = "Quais placas de identificação recebem o medalhão de classe acima do nome.", -- draft
	["Party and raid members"] = "Membros do grupo e da raide", -- draft
	["Every friendly player"] = "Todo jogador amistoso", -- draft
	["Marker Size"] = "Tamanho do marcador", -- draft
	["The medallion's size above the name."] = "O tamanho do medalhão acima do nome.", -- draft
	["Height Above The Name"] = "Altura acima do nome", -- draft
	["The gap between the name and the medallion."] = "A distância entre o nome e o medalhão.", -- draft
	["Role Ring"] = "Anel de função", -- draft
	["A coloured ring around the medallion for the member's assigned role: green healer, blue tank, red damage. Only when the group has roles set (the group finder sets them; a party can set them by hand)."] = "Um anel colorido ao redor do medalhão para a função atribuída ao membro: verde curador, azul tanque, vermelho dano. Só quando o grupo tem funções definidas (o localizador de grupos as define; um grupo pode defini-las à mão).", -- draft
	["Open world only: inside instances the game keeps friendly nameplates to itself"] = "Só no mundo aberto: dentro de instâncias o jogo reserva para si as placas de identificação amistosas", -- draft
	-- Sparkles
	["Loot Sparkles"] = "Brilhos de saque", -- draft
	["The game's sparkle on quest items you can loot, kept on through its graphics presets, and golden glints over the ore veins and herbs you walk up to: dim out of reach, bright in reach, grey when your skill is too low. The game settings it needs come back as you had them when it is off."] = "O brilho do jogo nos itens de missão que você pode saquear, mantido apesar das predefinições gráficas, e reflexos dourados sobre os veios de minério e as ervas de que você se aproxima: fracos fora de alcance, fortes ao alcance, cinza quando sua perícia é baixa demais. As configurações do jogo que isso exige voltam como você as tinha quando desligado.", -- draft
	["What you can loot, at a glance."] = "O que você pode saquear, num relance.", -- draft
	["Quest Item Sparkles"] = "Brilhos de itens de missão", -- draft
	["Keeps the game's sparkle on quest items you can loot. It needs the game's outline mode off, which its graphics presets switch back on: held while this is on, given back as you had it when off. Switching this off takes the sparkles away after the next game restart (the client's own; /reload is not enough)."] = "Mantém o brilho do jogo nos itens de missão que você pode saquear. Exige o modo de contorno do jogo desligado, que as predefinições gráficas religam: mantido enquanto isto está ligado, devolvido como você tinha quando desligado. Desligar isto tira os brilhos após o próximo reinício do jogo (o do cliente; /reload não basta).", -- draft
	["Ore Veins"] = "Veios de minério", -- draft
	["Golden glints over the ore vein you walk up to (the game's soft targeting picks the nearest one, within about 15 yards): dim out of reach, bright once you can mine it, grey when your skill is too low."] = "Reflexos dourados sobre o veio de minério de que você se aproxima (a seleção suave do jogo escolhe o mais próximo, a cerca de 15 metros): fracos fora de alcance, fortes quando você pode minerá-lo, cinza quando sua perícia é baixa demais.", -- draft
	["Herbs"] = "Ervas", -- draft
	["The same glints over the herb you walk up to."] = "Os mesmos reflexos sobre a erva de que você se aproxima.", -- draft
	["Quest Objects"] = "Objetos de missão", -- draft
	["The same glints over a quest object you walk up to. Off by default: the game's own sparkle (Quest Item Sparkles) already marks most of them."] = "Os mesmos reflexos sobre um objeto de missão de que você se aproxima. Desligado por padrão: o brilho do jogo (Brilhos de itens de missão) já marca a maioria.", -- draft
	-- CustomSounds
	["Custom Sounds"] = "Sons personalizados", -- draft
	["The interface's sounds replaced by the custom library: iron, leather, parchment and stone for clicks, windows, bags, gear, vendors, whispers and the group finder."] = "Os sons da interface trocados pela biblioteca personalizada: ferro, couro, pergaminho e pedra para cliques, janelas, bolsas, equipamento, comerciantes, sussurros e o localizador de grupos.", -- draft
	["Iron, leather, parchment and stone. Every click, page, pouch and buckle of the interface, re-recorded."] = "Ferro, couro, pergaminho e pedra. Cada clique, página, bolsinha e fivela da interface, regravados.", -- draft
	["Sounds"] = "Sons", -- draft
	["Clicks"] = "Cliques", -- draft
	["Buttons, checkboxes, tabs and scroll arrows: light clicks, a heavy one for Okay/Accept, a latch releasing for Cancel, Quit and abandoning a quest."] = "Botões, caixas de seleção, abas e setas de rolagem: cliques leves, um pesado para Ok/Aceitar, uma trava se soltando para Cancelar, Sair e abandonar uma missão.", -- draft
	["Windows"] = "Janelas", -- draft
	["A page turn when the character sheet, spell book, quest log or main menu opens, a latch when they close; the spell book's page turns; a quest giver's list and Decline; the bags as a leather pouch opening and closing."] = "Uma página virando quando a ficha do personagem, o grimório, o registro de missões ou o menu principal abre, uma trava quando fecham; as páginas do grimório; a lista de quem dá missões e Recusar; as bolsas como uma bolsinha de couro abrindo e fechando.", -- draft
	["Inventory"] = "Inventário", -- draft
	["An item picked up, moved between slots, put down or looted; a rare or better item has its own sound. Silences the game's own pick-up and put-down sounds (the Equipment and Vendor sounds rely on that, and play only while this is on)."] = "Um item pego, movido entre compartimentos, largado ou saqueado; um item raro ou melhor tem som próprio. Silencia os sons de pegar e largar do jogo (os sons de Equipamento e Comerciante dependem disso, e só tocam enquanto isto está ligado).", -- draft
	["Equipment"] = "Equipamento", -- draft
	["Buckles and plate for armour, a steel slide for weapons, jewellery ticks for rings, necks and trinkets; straps loosening when something is taken off."] = "Fivelas e placas para armaduras, um deslizar de aço para armas, tilintar de joias para anéis, colares e berloques; correias afrouxando quando algo é tirado.", -- draft
	["Coins on the counter when buying, coins into the pouch when selling (the automatic grey sale too)."] = "Moedas no balcão ao comprar, moedas na bolsinha ao vender (a venda automática do cinza também).", -- draft
	["Social"] = "Social", -- draft
	["A note under the door for a whisper, two knocks for a group invite."] = "Um bilhete por baixo da porta para um sussurro, duas batidas para um convite de grupo.", -- draft
	["Group Finder"] = "Localizador de grupos", -- draft
	["The ledger for entering a queue or applying to a listing, a strike-through for leaving it, the bell for a group that is ready and for a ready check."] = "O livro de registro ao entrar numa fila ou se candidatar a um anúncio, um risco ao sair, o sino para um grupo pronto e para uma verificação de prontidão.", -- draft
	["The workbench when an item is crafted."] = "A bancada quando um item é criado.", -- draft
	["Quests"] = "Missões", -- draft
	["The mechanism engaging when a quest is turned in."] = "O mecanismo engatando quando uma missão é entregue.", -- draft
	["Errors"] = "Erros", -- draft
	["A muted knock for the game's red error messages (\"You can't do that yet\"), at most one every half second; none for a message Error Messages hides."] = "Uma batida abafada para as mensagens de erro vermelhas do jogo (\"Você ainda não pode fazer isso\"), no máximo uma a cada meio segundo; nenhuma para uma mensagem que Mensagens de erro esconde.", -- draft
	["Targets"] = "Alvos", -- draft
	["An iron sight catching when a target is selected, a latch releasing when it is lost."] = "Uma mira de ferro engatando quando um alvo é selecionado, uma trava se soltando quando ele é perdido.", -- draft
	["A seal struck into the record when you level."] = "Um selo carimbado no registro quando você sobe de nível.", -- draft
	["Loot Coins"] = "Moedas do saque", -- draft
