	["Smooth Bars"] = "Barras suaves", -- draft
	["The bars glide to a new value instead of jumping."] = "As barras deslizam até um novo valor em vez de pular.", -- draft
	["What lies behind the health bar: a flat colour (Background Colour), one of MelloUI's backgrounds (stone, concrete, parchment, the dark gradients...), or none."] = "O que fica atrás da barra de vida: uma cor lisa (Cor de fundo), um dos fundos do MelloUI (pedra, concreto, pergaminho, os degradês escuros...) ou nada.", -- draft
	["Flat colour"] = "Cor lisa", -- draft
	["Background Colour"] = "Cor de fundo", -- draft
	["The colour behind the health bar: one of yours, or the member's class colour."] = "A cor atrás da barra de vida: uma das suas, ou a cor da classe do membro.", -- draft
