	["How solid the background is."] = "O quanto o fundo é sólido.", -- draft
	["Missing Health"] = "Vida perdida", -- draft
	["The part of the bar a member has lost, in a colour of its own: yours, their class colour, or by health."] = "A parte da barra que um membro perdeu, numa cor própria: a sua, a cor da classe dele, ou por vida.", -- draft
