	["Power Bar Height"] = "Altura da barra de recurso", -- draft
	["How tall the power bar is."] = "A altura da barra de recurso.", -- draft
	["Power Colour"] = "Cor do recurso", -- draft
	["The power bar's colour: the power's own (blue mana, red rage, yellow energy), the member's class colour, or one of yours."] = "A cor da barra de recurso: a do próprio recurso (mana azul, raiva vermelha, energia amarela), a cor da classe do membro, ou uma das suas.", -- draft
	["Power Type"] = "Tipo de recurso", -- draft
