	["The power bar's colour with My Colour."] = "A cor da barra de recurso com Minha cor.", -- draft
	["Name Colour"] = "Cor do nome", -- draft
	["The name's colour: white, the member's class colour, or one of yours."] = "A cor do nome: branco, a cor da classe do membro, ou uma das suas.", -- draft
	["White"] = "Branco", -- draft
	["My Name Colour"] = "Minha cor de nome", -- draft
	["The name's colour with My Colour."] = "A cor do nome com Minha cor.", -- draft
	["Name Length"] = "Tamanho do nome", -- draft
	["The most letters of a name shown (0: the whole name)."] = "O máximo de letras de um nome mostradas (0: o nome inteiro).", -- draft
	["Health Text"] = "Texto de vida", -- draft
	["The health shown as text: its percent, the current health, or how much is missing."] = "A vida mostrada como texto: a porcentagem, a vida atual, ou quanto falta.", -- draft
